+      canvas.width = canvas.height = 1;
+      const context = canvas.getContext('2d', { willReadFrequently: true });
+
+      function updateContrast() {
+        for (const [surface, property] of surfaces) {
+          context.clearRect(0, 0, 1, 1);
+          context.fillStyle = getComputedStyle(surface).backgroundColor;
+          context.fillRect(0, 0, 1, 1);
+          const channels = context.getImageData(0, 0, 1, 1).data;
+          const linear = Array.from(channels).slice(0, 3).map(value => {
+            const channel = value / 255;
+            return channel <= 0.04045
+              ? channel / 12.92
+              : ((channel + 0.055) / 1.055) ** 2.4;
+          });
+          const luminance = linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
+          const foreground = (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05)
+            ? '#000' : '#fff';
