+// Build a real smallpt preview from the compiled Wasm; no browser/server required.
+import { readFileSync, writeFileSync } from 'node:fs';
+import { deflateSync } from 'node:zlib';
+globalThis.self = globalThis;
+globalThis.location = { href: new URL('../assets/smallpt.mjs', import.meta.url).href };
+const { default: createSmallpt } = await import('../assets/smallpt.mjs');
+const wasm = await createSmallpt({ wasmBinary: readFileSync(new URL('../assets/smallpt.wasm', import.meta.url)) });
+const w=720,h=540,ptr=wasm._setup(w,h);
+wasm._material(0,.72,.19,.065,0);
+wasm._material(1,.94,.84,.66,2);
+for(let y=0;y<h;y+=4) wasm._render_rows(y,4,256,42);
+const rgba=wasm.HEAPU8.slice(ptr,ptr+w*h*4);
+const raw=Buffer.alloc(h*(w*4+1));
+for(let y=0;y<h;y++)raw.set(rgba.subarray(y*w*4,(y+1)*w*4),y*(w*4+1)+1);
+function crc(buf){let c=0xffffffff;for(const b of buf){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}
+function chunk(type,data){const name=Buffer.from(type),len=Buffer.alloc(4),sum=Buffer.alloc(4);len.writeUInt32BE(data.length);sum.writeUInt32BE(crc(Buffer.concat([name,data])));return Buffer.concat([len,name,data,sum]);}
+const hdr=Buffer.alloc(13);hdr.writeUInt32BE(w);hdr.writeUInt32BE(h,4);hdr[8]=8;hdr[9]=6;
+writeFileSync(new URL('../assets/preview.png',import.meta.url),Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',hdr),chunk('IDAT',deflateSync(raw)),chunk('IEND',Buffer.alloc(0))]));
+console.log('Built 720 × 540 smallpt WebAssembly preview (256 spp).');
