+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// Browser adaptation: keep the original integrator, render a contiguous row
+// buffer, and expose scene colors. Kevin Beason's MIT license is in LICENSE.txt.
+#include <stdint.h>
+extern "C" {
+void set_color(int id, double r, double g, double b) {
+  if (id == 0 || id == 1 || id == 6 || id == 7) spheres[id].c = Vec(r,g,b);
+}
+void render_rows(unsigned char *pixels, int w, int h, int first, int count,
+                 int samples, unsigned seed) {
+  Ray cam(Vec(50,52,295.6), Vec(0,-0.042612,-1).norm());
+  Vec cx=Vec(w*.5135/h), cy=(cx%cam.d).norm()*.5135;
+  int samps=samples/4;
+  for (int row=first; row<first+count && row<h; ++row) {
+    int y=h-row-1;
+    unsigned short Xi[3]={(unsigned short)seed,(unsigned short)(seed>>16),
+                         (unsigned short)(y*y*y)};
+    for (int x=0; x<w; ++x) {
+      Vec color;
+      for (int sy=0; sy<2; ++sy) for (int sx=0; sx<2; ++sx) {
+        Vec r;
+        for (int s=0; s<samps; ++s) {
+          double r1=2*erand48(Xi), dx=r1<1?sqrt(r1)-1:1-sqrt(2-r1);
+          double r2=2*erand48(Xi), dy=r2<1?sqrt(r2)-1:1-sqrt(2-r2);
+          Vec d=cx*(((sx+.5+dx)/2+x)/w-.5)+cy*(((sy+.5+dy)/2+y)/h-.5)+cam.d;
+          r=r+radiance(Ray(cam.o+d*140,d.norm()),0,Xi)*(1./samps);
+        }
+        color=color+Vec(clamp(r.x),clamp(r.y),clamp(r.z))*.25;
+      }
+      int i=((row-first)*w+x)*4;
+      pixels[i]=toInt(color.x); pixels[i+1]=toInt(color.y);
+      pixels[i+2]=toInt(color.z); pixels[i+3]=255;
+    }
+  }
+}
+}
