+const get = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
+const canvas = get<HTMLCanvasElement>('render-canvas');
+const ctx = canvas.getContext('2d')!;
+const preview = get<HTMLImageElement>('preview');
+const status = get('render-status');
+const count = get('sample-count');
+const time = get('render-time');
+const progress = get('progress');
+const resolution = get<HTMLSelectElement>('resolution');
+const originals: Record<number, string> = { 0: '#bf4040', 1: '#4040bf', 6: '#ffffff', 7: '#ffffff' };
+let samples = 64;
+let worker: Worker | undefined;
+let hasFrame = false;
+let started = 0;
+let clock: ReturnType<typeof setInterval>;
+let changeTimer: ReturnType<typeof setTimeout>;
+
+function colorData() {
+  return Object.fromEntries(Object.keys(originals).map((key) => {
+    const hex = get<HTMLInputElement>(`color-${key}`).value;
+    return [key, [1, 3, 5].map((offset) => Math.min(.999, parseInt(hex.slice(offset, offset + 2), 16) / 255))];
+  }));
+}
+function updateColor(id: string | number, value: string) {
+  const input = get<HTMLInputElement>(`color-${id}`);
+  input.value = value;
+  get(`hex-${id}`).textContent = value.toUpperCase();
+  const row = input.closest('.color-row')!;
+  (row.querySelector('.color-indicator') as HTMLElement).style.background = value;
+}
+function stopClock() { clearInterval(clock); }
+function render() {
+  clearTimeout(changeTimer);
+  worker?.terminate();
+  stopClock();
+  const width = Number(resolution.value), height = width * 3 / 4;
+  status.textContent = 'Rendering';
+  count.textContent = `0 / ${samples} spp`;
+  get('dimensions').textContent = `${width} × ${height}`;
+  get('engine-label').textContent = 'WebAssembly active';
+  get('render-dot').style.background = '#88a77b';
+  progress.style.width = '0%';
+  started = performance.now();
+  clock = setInterval(() => { time.textContent = `${((performance.now() - started) / 1000).toFixed(1)}s`; }, 100);
+  const fail = () => {
+    stopClock();
+    status.textContent = 'Render unavailable';
+    get('engine-label').textContent = 'Could not load WebAssembly';
+    get('render-dot').style.background = '#be6d55';
+    get('randomize').title = 'Click to retry rendering with a new palette';
+    worker?.terminate();
+  };
+  try {
+    worker = new Worker(`${import.meta.env.BASE_URL}wasm/render-worker.js`);
+    worker.onerror = fail;
+    worker.onmessage = ({ data }) => {
+      if (data.type === 'error') { console.error('smallpt:', data.message); fail(); return; }
+      if (data.type === 'progress') progress.style.width = `${data.progress * 100}%`;
+      if (data.type === 'frame') {
+        if (canvas.width !== data.width || canvas.height !== data.height) {
+          canvas.width = data.width; canvas.height = data.height;
+        }
+        ctx.putImageData(new ImageData(new Uint8ClampedArray(data.buffer), data.width, data.height), 0, 0);
+        canvas.classList.add('ready');
+        hasFrame = true;
+        count.textContent = `${data.samples} / ${samples} spp`;
+        if (data.done) {
+          stopClock();
+          time.textContent = `${data.elapsed.toFixed(1)}s`;
+          status.textContent = 'Render complete';
+          progress.style.width = '100%';
+          worker?.terminate();
+        }
+      }
+    };
+    const seed = crypto.getRandomValues(new Uint32Array(1))[0];
+    worker.postMessage({ width, height, samples, seed, colors: colorData() });
+  } catch (error) { console.error(error); fail(); }
+}
+function randomHex(bright = false) {
+  const values = crypto.getRandomValues(new Uint8Array(3));
+  return '#' + Array.from(values, (value) => Math.round(bright ? 180 + value / 255 * 75 : 55 + value / 255 * 155).toString(16).padStart(2, '0')).join('');
+}
+get('randomize').addEventListener('click', () => {
+  for (const id of Object.keys(originals)) updateColor(id, randomHex(Number(id) >= 6));
+  render();
+});
+get('reset').addEventListener('click', () => {
+  for (const [id, color] of Object.entries(originals)) updateColor(id, color);
+  render();
+});
+for (const id of Object.keys(originals)) {
+  const input = get<HTMLInputElement>(`color-${id}`);
+  input.addEventListener('input', () => {
+    updateColor(id, input.value);
+    clearTimeout(changeTimer);
+    changeTimer = setTimeout(render, 300);
+  });
+}
+document.querySelectorAll<HTMLButtonElement>('[data-samples]').forEach((button) => {
+  button.setAttribute('aria-pressed', String(button.classList.contains('selected')));
+  button.addEventListener('click', () => {
+    samples = Number(button.dataset.samples);
+    document.querySelectorAll('[data-samples]').forEach((item) => {
+      item.classList.toggle('selected', item === button);
+      item.setAttribute('aria-pressed', String(item === button));
+    });
+    render();
+  });
+});
+resolution.addEventListener('change', render);
+get('download').addEventListener('click', async () => {
+  if (!hasFrame) {
+    try {
+      await preview.decode();
+      canvas.width = preview.naturalWidth; canvas.height = preview.naturalHeight;
+      ctx.drawImage(preview, 0, 0);
+    } catch { status.textContent = 'Image is still loading'; return; }
+  }
+  canvas.toBlob((blob) => {
+    if (!blob) return;
+    const url = URL.createObjectURL(blob);
+    const link = document.createElement('a');
+    link.download = `smallpt-${Date.now()}.png`; link.href = url; link.click();
+    setTimeout(() => URL.revokeObjectURL(url), 1000);
+  }, 'image/png');
+});
+get('expand').addEventListener('click', async () => {
+  try {
+    if (document.fullscreenElement) await document.exitFullscreen();
+    else await get('viewport').requestFullscreen();
+  } catch { status.textContent = 'Fullscreen unavailable'; }
+});
+const about = get<HTMLDialogElement>('about-dialog');
+get('about-open').addEventListener('click', () => about.showModal());
+get('about-close').addEventListener('click', () => about.close());
+about.addEventListener('click', (event) => { if (event.target === about) { const r = about.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) about.close(); } });
+window.addEventListener('pagehide', () => { worker?.terminate(); stopClock(); });
+render();

