+  <script>
+    const actionTarget = document.getElementById('action-target');
+    const actionButtons = document.querySelectorAll('button[commandfor="action-target"]');
+    const commandClasses = new Map([
+      ['--spin', 'is-spun'],
+      ['--grow', 'is-grown'],
+      ['--round', 'is-rounded'],
+    ]);
+
+    actionTarget.addEventListener('command', (event) => {
+      if (event.command === '--reset') {
+        actionTarget.classList.remove(...commandClasses.values());
+      } else if (commandClasses.has(event.command)) {
+        actionTarget.classList.toggle(commandClasses.get(event.command));
+      } else {
+        return;
+      }
+
+      actionButtons.forEach((button) => {
+        const className = commandClasses.get(button.getAttribute('command'));
+        if (className) {
+          button.setAttribute('aria-pressed', String(actionTarget.classList.contains(className)));
+        }
+      });
+    });
+
+    // Dispatch the same command event on browsers without native invoker support.
+    if (!('commandForElement' in HTMLButtonElement.prototype)) {
+      actionButtons.forEach((button) => {
+        button.addEventListener('click', () => {
+          const event = new Event('command');
+          event.command = button.getAttribute('command');
