+          (next as HTMLElement | null ?? item?.closest('dialog')?.querySelector('button'))?.focus();
+          await remove(article.slug);
+        }} className="p-2 text-gray-600">Remove</button>
+    </li>)}</ul>
+  </div>;
 }
