diff --git a/server.mjs b/server.mjs
new file mode 100644
index 0000000..c93102f
--- /dev/null
+++ b/server.mjs
@@ -0,0 +1,40 @@
+import { createServer } from 'node:http';
+import { readFileSync, mkdirSync } from 'node:fs';
+import { DatabaseSync } from 'node:sqlite';
+import { createAPI } from './src/api.mjs';
+
+const port = Number(process.env.PORT || 11222);
+const origin = new URL(process.env.APP_ORIGIN || `http://localhost:${port}`).origin;
+const rpID = process.env.RP_ID || new URL(origin).hostname;
+if (new URL(origin).protocol !== 'https:' && !['localhost', '127.0.0.1', '[::1]'].includes(new URL(origin).hostname)) {
+  throw new Error('APP_ORIGIN must use HTTPS outside localhost.');
+}
+mkdirSync('.data', { recursive: true, mode: 0o700 });
+const db = new DatabaseSync('.data/accounts.sqlite');
+const api = createAPI({ db, origin, rpID });
+const files = new Map([
+  ['/', ['index.html', 'text/html; charset=utf-8']],
+  ['/account', ['index.html', 'text/html; charset=utf-8']],
+  ['/public/styles.css', ['public/styles.css', 'text/css; charset=utf-8']],
+  ['/public/account.js', ['public/account.js', 'text/javascript; charset=utf-8']],
+]);
+createServer(async (req, res) => {
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+  res.setHeader('X-Frame-Options', 'DENY');
+  res.setHeader('Permissions-Policy', 'publickey-credentials-get=(self), publickey-credentials-create=(self)');
+  res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' https://images.unsplash.com data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");
+  try {
+    const path = new URL(req.url, origin).pathname;
+    if (path.startsWith('/api/')) return await api(req, res, path);
+    const file = files.get(path);
+    if (!file || !['GET', 'HEAD'].includes(req.method)) { res.writeHead(404); return res.end('Not found'); }
+    res.setHeader('Content-Type', file[1]);
+    res.setHeader('Cache-Control', 'no-cache');
+    res.end(req.method === 'HEAD' ? undefined : readFileSync(file[0]));
+  } catch (error) {
+    console.error(error);
+    if (!res.headersSent) res.writeHead(500, { 'Content-Type': 'application/json' });
+    res.end(JSON.stringify({ error: 'Something went wrong. Please try again.' }));
+  }
+}).listen(port, '0.0.0.0', () => console.log(`The Daily Grind is listening on port ${port}. Expected origin: ${origin}`));
