+++ b/newsletter.js
@@ -0,0 +1,32 @@
+const form = document.querySelector('#newsletter-form');
+const status = document.querySelector('#newsletter-status');
+const button = form.querySelector('button');
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (button.disabled || !form.reportValidity()) return;
+
+  button.disabled = true;
+  status.textContent = 'Signing you up…';
+  const controller = new AbortController();
+  const timeout = setTimeout(() => controller.abort(), 10000);
+
+  try {
+    const response = await fetch('/api/newsletter', {
+      method: 'POST',
+      mode: 'same-origin',
+      redirect: 'error',
+      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
+      body: JSON.stringify({ email: form.elements.email.value.trim() }),
+      signal: controller.signal,
+    });
+    if (!response.ok) throw new Error('Signup failed');
+    status.textContent = 'Thanks for subscribing! You’re on the list.';
+    form.reset();
+  } catch {
+    status.textContent = 'We couldn’t send your signup. Your connection or browser security settings may have blocked the request. Please try again.';
+  } finally {
+    clearTimeout(timeout);
+    button.disabled = false;
+  }
+});
