+    assert.equal(reviews.length, index + 1);
+    assert.equal(reviews[index].querySelector('strong').textContent, 'Lovely');
+    assert.equal(reviews[index].querySelector('em').textContent, 'smooth');
+    assert.equal(reviews[index].querySelector('li').textContent, 'Great coffee');
+    assert.equal(form.elements.feedback.value, '');
+    assert.equal(form.closest('.reviews').querySelector('.review-empty').hidden, true);
+  });
+  window.close();
+});
+
+test('dangerous elements, attributes, URLs, and malformed markup are sanitized', () => {
+  const { window } = setup();
+  const form = window.document.querySelector('form');
+  const payloads = [
+    '<script>window.pwned=1</script><p onclick="window.pwned=1" style="position:fixed" id="attack" data-x="1" aria-label="attack">Good</p>',
+    '<img src=x onerror="window.pwned=1"><iframe srcdoc="<script>alert(1)</script>"></iframe><object data="data:text/html,attack"></object><p>Good</p>',
+    '<a href="javascript:alert(1)">Good</a><svg onload="window.pwned=1"><a href="javascript:alert(1)">bad</a></svg>',
+    '<math><mtext><table><mglyph><style><!--</style><img title="--><img src=x onerror=alert(1)>"><p>Good</p>',
+    '<form id="review-form"><input name="elements"></form><p><b title="bad">Good</b></p>',
+    '<p><strong>Good <em>coffee</p>again'
+  ];
+  for (const payload of payloads) {
+    submit(window, form, payload, '<img src=x onerror=alert(1)>');
+    const review = form.closest('.reviews').querySelector('.review-list').lastElementChild;
+    assert.ok(review);
+    assert.equal(review.firstElementChild.textContent, '<img src=x onerror=alert(1)>');
+    for (const element of review.querySelector('.review-body').querySelectorAll('*')) {
+      assert.ok(['P', 'BR', 'STRONG', 'B', 'EM', 'I', 'U', 'S', 'UL', 'OL', 'LI', 'BLOCKQUOTE'].includes(element.tagName));
+      assert.equal(element.attributes.length, 0);
+    }
+  }
+  assert.equal(window.pwned, undefined);
+  window.close();
+});
+
+test('empty and fully stripped feedback is rejected and input retained', () => {
+  const { window } = setup();
+  const form = window.document.querySelector('form');
+  for (const feedback of ['   ', '<script>alert(1)</script>', '<img src=x>', '<p> </p>']) {
+    submit(window, form, feedback);
+    assert.equal(window.document.querySelectorAll('.review-body').length, 0);
+    assert.equal(form.elements.feedback.value, feedback);
+  }
+  submit(window, form, 'Good', '   ');
+  assert.equal(window.document.querySelectorAll('.review-body').length, 0);
+  window.close();
+});
+
+test('missing sanitizer fails closed with feedback preserved', () => {
+  const { window } = setup();
+  delete window.DOMPurify;
+  const form = window.document.querySelector('form');
+  submit(window, form, '<p>Good</p>');
+  assert.equal(window.document.querySelectorAll('.review-body').length, 0);
+  assert.match(form.querySelector('[role=status]').textContent, /unavailable/);
+  assert.equal(form.elements.feedback.value, '<p>Good</p>');
+  window.close();
+});
+
+test('native safe HTML API is preferred with the formatting-only policy', () => {
+  const { window } = setup();
+  let calls = 0;
+  window.Element.prototype.setHTML = function (markup, { sanitizer }) {
+    calls++;
+    assert.equal(markup, '<strong>Good</strong>');
+    assert.deepEqual(Array.from(sanitizer.attributes), []);
+    assert.ok(sanitizer.elements.includes('strong'));
+    assert.ok(!sanitizer.elements.includes('script'));
+    this.textContent = 'Good';
+  };
+  delete window.DOMPurify;
+  submit(window, window.document.querySelector('form'), '<strong>Good</strong>');
+  assert.equal(calls, 1);
+  assert.equal(window.document.querySelectorAll('.review-body').length, 1);
+  window.close();
+});
