@@ -0,0 +1,23 @@
+for (const button of document.querySelectorAll('[data-dialog]')) {
+  button.addEventListener('click', () => document.getElementById(button.dataset.dialog).showModal());
+}
+for (const dialog of document.querySelectorAll('dialog')) {
+  for (const button of dialog.querySelectorAll('.dialog-close, .dialog-done')) {
+    button.addEventListener('click', () => dialog.close());
+  }
+  dialog.addEventListener('click', event => { if (event.target === dialog) {
+    const box = dialog.getBoundingClientRect();
+    if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) dialog.close();
+  }});
+}
+// Keep native form submission: the browser adds the verification token at submission.
+// Intercepting submission to send fetch/FormData can omit the browser-provided token.
+document.getElementById('rewards-form')?.addEventListener('submit', event => {
+  const button = event.target.querySelector('[type="submit"]');
+  button.disabled = true;
+  button.textContent = 'Verifying your email…';
+});
+window.addEventListener('pageshow', () => {
+  const button = document.querySelector('#rewards-form [type="submit"]');
+  if (button) { button.disabled = false; button.innerHTML = 'Create my rewards account <span aria-hidden="true">↗</span>'; }
+});
